INSERT OR IGNORE INTO schema_migrations (id) VALUES ('catalog-v1');
CREATE TABLE IF NOT EXISTS region_discovery (region_code TEXT PRIMARY KEY NOT NULL REFERENCES regions(code) ON DELETE CASCADE, retired INTEGER NOT NULL DEFAULT 0 CHECK (retired IN (0, 1)));
CREATE VIEW IF NOT EXISTS active_regions AS SELECT r.* FROM regions r WHERE NOT EXISTS (SELECT 1 FROM region_discovery d WHERE d.region_code = r.code AND d.retired = 1);
CREATE VIEW IF NOT EXISTS active_endpoints AS SELECT e.* FROM endpoints e WHERE NOT EXISTS (SELECT 1 FROM region_discovery d WHERE d.region_code = e.region_code AND d.retired = 1);
INSERT OR IGNORE INTO region_discovery (region_code) SELECT r.code FROM regions r WHERE NOT EXISTS (SELECT 1 FROM schema_migrations WHERE id = 'region-discovery-v1') AND (r.code IN ('GRU', 'SJC', 'FRA') OR EXISTS (SELECT 1 FROM endpoints e WHERE e.region_code = r.code AND e.component_id = '01M4E7G1W82VKFPF5FJ9AVK1D2' AND e.cluster = lower(r.code) AND e.provider = 'other' AND e.kind = 'http' AND e.url LIKE 'https://%.terrascale.tech/healthz' AND e.assertions = json_array(json_object('path', 'status', 'op', 'eq', 'value', 'ok'), json_object('path', 'region', 'op', 'eq', 'value', lower(r.code)))));
UPDATE endpoints SET region_code = 'GRU' WHERE id = '01M4PVGGBHD58R8HYNDBTGFRGJ' AND region_code IS NULL AND url = 'https://gru.api.terrascale.tech/v1/regions' AND EXISTS (SELECT 1 FROM regions WHERE code = 'GRU') AND NOT EXISTS (SELECT 1 FROM schema_migrations WHERE id = 'region-discovery-v1');
INSERT OR IGNORE INTO schema_migrations (id) VALUES ('region-discovery-v1');
